#include <queue>
#include <vector>
#include <functional>

// Default: Max Heap (uses std::vector and std::less)
std::priority_queue<int> max_q;

// Custom: Min Heap (uses std::vector and std::greater)
// The order of template arguments (T, Container, Compare) is fixed.
std::priority_queue<int, std::vector<int>, std::greater<int>> min_q;

int main() {
    max_q.push(10); max_q.push(5);
    min_q.push(10); min_q.push(5);

    // Max Heap: 10
    std::cout << "Max Top: " << max_q.top() << '\n';
    // Min Heap: 5
    std::cout << "Min Top: " << min_q.top() << '\n';
}
